def count_passing_ways(n, m):
    # Initialize a two-dimensional array to store the results of subproblems
    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the first row of the dp array
    for i in range(n):
        dp[i][0] = 1

    # Fill in the dp array using the recurrence relation
    for i in range(1, m + 1):
        for j in range(n):
            if j - 1 >= 0:
                dp[j][i] += dp[j - 1][i - 1]
            if j + 1 < n:
                dp[j][i] += dp[j + 1][i - 1]

    # Return the last value in the last row of the dp array
    return dp[n - 1][m]

