def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D array to store the number of passing ways
    # dp[i][j] represents the number of ways to pass the ball among i students in j passes
    dp = [[0] * (m + 1) for _ in range(n)]

    # Initialize the first row of the dp table
    for i in range(n):
        dp[i][0] = 1

    # Fill in the dp table using the recurrence relation
    for j in range(1, m + 1):
        for i in range(n):
            # Case 1: Pass the ball to the right neighbor
            if i < n - 1:
                dp[i][j] += dp[i + 1][j - 1]
            # Case 2: Pass the ball to the left neighbor
            if i > 0:
                dp[i][j] += dp[i - 1][j - 1]

    # Return the number of passing ways that result in the ball returning to the starting student
    return dp[0][m]

