    n = len(heights)
    inc = True
    dec = True
    min_leave = n

    # Check if the heights are already in descending order
    if heights == sorted(heights, reverse=True):
        return 0

    # Iterate over the heights and check if the sequence is increasing or decreasing
    for i in range(1, n):
        if inc and heights[i] > heights[i-1]:
            inc = True
        elif dec and heights[i] < heights[i-1]:
            dec = True
        else:
            inc = False
            dec = False
            break

    # If the sequence is increasing, leave the last student
    if inc:
        return 1

    # If the sequence is decreasing, leave the first student
    if dec:
        return 1

    # If the sequence is a mix of increasing and decreasing, leave the minimum number of students
    # to form a decreasing sequence
    for i in range(1, n):
        if heights[i] < heights[i-1]:
            min_leave = i
            break

    return n - min_leave

